begin;
do $qa$
declare k text:=encode(gen_random_bytes(32),'hex'); p jsonb:='{"schemaVersion":1,"id":"escape-transaction-qa","title":"The Evidence Protocol","subtitle":"A learning escape room about decisions under uncertainty","briefing":"An urgent recommendation is about to be sent without a full review. Enter the briefing room, examine the evidence, and restore the decision process before time runs out. Every clue has a purpose. Every assumption needs a check.","learningGoals":"Distinguish evidence from assumptions.\nCheck information before taking action.\nEvaluate a decision before committing to it.","debrief":"What information did you initially assume was true?\nHow did checking the evidence change your decisions?\nWhere does your team need a stronger verification step?","duration":20,"startSceneId":"briefing","updatedAt":1792004514648,"scenes":[{"id":"briefing","name":"The briefing room","description":"Inspect the file, unlock the case, and find your way into the lab.","background":{"type":"illustration","art":"briefing","data":""},"view":{"yaw":0,"pitch":0,"fov":75},"objects":[{"id":"evidence-note","name":"Evidence summary","type":"clue","visual":"folder","x":30,"y":52,"w":9,"h":15,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"A sound recommendation needs a clear trail of evidence.\n\n4 corroborated sources\n3 unanswered questions\n1 proposed action\n\nThe case code follows that order: sources, questions, action.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Inspect the evidence folder on the desk."]},{"id":"evidence-case","name":"Evidence case","type":"code","visual":"safe","x":69,"y":61,"w":14,"h":18,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"A three-digit code protects the verification key. Use the figures in the evidence summary, in the order shown.","answer":"431","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":["verification-key"],"destination":"","success":"Case unlocked. The verification key is now on the desk.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Inspect the folder on the desk.","Count the sources, questions, and action—in that order.","The case code is 431."]},{"id":"verification-key","name":"Verification key","type":"item","visual":"key","x":52,"y":61,"w":7,"h":11,"yaw":0,"pitch":0,"rotation":0,"hidden":true,"body":"A brass key marked VERIFY. Use it on the lab door.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]},{"id":"lab-door","name":"Lab door","type":"target","visual":"door","x":83,"y":34,"w":15,"h":42,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"The evidence lab is locked. Find the verification key.","answer":"","alternatives":[],"accepts":"verification-key","placement":"consume","requires":[],"reveal":[],"destination":"lab","success":"The key fits. Welcome to the evidence lab.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Unlock the evidence case to find the key.","Drag the key to this door, or select it and then click the door."]},{"id":"briefing-plant","name":"Desk plant","type":"decoration","visual":"plant","x":6,"y":41,"w":9,"h":24,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]}]},{"id":"lab","name":"The evidence lab","description":"Assemble the containment unit, then evaluate the next step.","background":{"type":"illustration","art":"lab","data":""},"view":{"yaw":0,"pitch":0,"fov":75},"objects":[{"id":"lab-note","name":"Assembly instructions","type":"clue","visual":"note","x":28,"y":55,"w":9,"h":17,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"Uncontrolled information can spread before it is tested. Assemble the containment unit before reading its results.\n\nFit the round lid onto the open container. You can drag it directly from the workbench.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Inspect the assembly instructions."]},{"id":"container-lid","name":"Container lid","type":"item","visual":"lid","x":44,"y":56,"w":10,"h":13,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"A round lid with a secure handle. It fits the open containment unit.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]},{"id":"containment-unit","name":"Containment unit","type":"target","visual":"pod","x":63,"y":55,"w":13,"h":20,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"This unit needs its lid before the results can be read.","answer":"","alternatives":[],"accepts":"container-lid","placement":"attach","requires":[],"reveal":["evaluation-note"],"destination":"","success":"The lid is fitted. A result card is now available.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Find the loose lid on the workbench.","Drag the lid over this container."]},{"id":"evaluation-note","name":"Result card","type":"clue","visual":"note","x":50,"y":61,"w":9,"h":15,"yaw":0,"pitch":0,"rotation":0,"hidden":true,"body":"A decision process is only as strong as the review before action.\n\nBefore committing, EVALUATE the evidence: its quality, relevance, and limits.\n\nEnter the emphasized word into the review panel.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]},{"id":"review-panel","name":"Review panel","type":"code","visual":"console","x":76,"y":47,"w":14,"h":21,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"Enter the action you should take before committing to a consequential decision.","answer":"EVALUATE","alternatives":[],"accepts":"","placement":"consume","requires":["containment-unit"],"reveal":[],"destination":"","success":"Review passed. The command room is available.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Assemble the containment unit first.","Read the result card revealed on the workbench.","Enter EVALUATE."]},{"id":"command-door","name":"Command room door","type":"portal","visual":"door","x":88,"y":30,"w":11,"h":39,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"The review panel must be cleared before you can enter.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":["review-panel"],"reveal":[],"destination":"command","success":"Entering mission control.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]},{"id":"lab-back","name":"Return to briefing","type":"portal","visual":"marker","x":3,"y":68,"w":6,"h":10,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"briefing","success":"Returning to the briefing room.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]}]},{"id":"command","name":"Mission control","description":"Make the final decision and restore the evidence protocol.","background":{"type":"illustration","art":"command","data":""},"view":{"yaw":0,"pitch":0,"fov":75},"objects":[{"id":"final-brief","name":"Final decision brief","type":"clue","visual":"folder","x":29,"y":61,"w":10,"h":16,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"An unconfirmed report has just arrived. It supports the recommendation, but there is no second source.\n\nYour options: ACT immediately, IGNORE the report, or VERIFY the information.\n\nThe protocol requires evidence before commitment. Type the best next action into the release panel.","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"","success":"Puzzle solved.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]},{"id":"release-panel","name":"Release panel","type":"finish","visual":"console","x":61,"y":55,"w":17,"h":22,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"What should you do with the unconfirmed report before taking action?","answer":"VERIFY","alternatives":[],"accepts":"","placement":"consume","requires":["review-panel"],"reveal":[],"destination":"","success":"Evidence protocol restored. Your team can now make a supported decision.","incorrect":"","locked":"Solve the connected puzzles first.","hints":["Read the final decision brief.","Choose the action that checks the unconfirmed report.","Enter VERIFY."]},{"id":"command-back","name":"Return to lab","type":"portal","visual":"marker","x":8,"y":65,"w":7,"h":12,"yaw":0,"pitch":0,"rotation":0,"hidden":false,"body":"","answer":"","alternatives":[],"accepts":"","placement":"consume","requires":[],"reveal":[],"destination":"lab","success":"Returning to the evidence lab.","incorrect":"","locked":"Solve the connected puzzles first.","hints":[]}]}]}'::jsonb;
 r jsonb; asset text:='asset-'||repeat('a',64); extra_asset text:='asset-'||repeat('b',64);
 tok text:=encode(gen_random_bytes(24),'hex'); sid uuid:=gen_random_uuid(); proof text:=encode(gen_random_bytes(24),'hex');
begin
 insert into ml_authoring.gateway_keys(key_hash) values(encode(sha256(convert_to(k,'UTF8')),'hex'));
 begin perform ml_escape.gateway('invalid','list','{}'::jsonb);raise exception 'An invalid gateway key was accepted';exception when insufficient_privilege then null;end;
 r:=ml_escape.gateway(k,'save',jsonb_build_object('id',p->>'id','version',0,'data',p,'assets','[]'::jsonb));
 if r->>'version'<>'1' then raise exception 'Initial save failed';end if;
 begin perform ml_escape.gateway(k,'save',jsonb_build_object('id',p->>'id','version',0,'data',p,'assets','[]'::jsonb));raise exception 'A stale save was accepted';exception when serialization_failure then null;end;
 perform ml_escape.gateway(k,'asset-init',jsonb_build_object('id',asset,'mime','image/png','parts',1));
 begin perform ml_escape.gateway(k,'asset',jsonb_build_object('id',asset));raise exception 'Incomplete upload was readable';exception when no_data_found then null;end;
 perform ml_escape.gateway(k,'asset-part',jsonb_build_object('id',asset,'part',0,'data','AA=='));
 perform ml_escape.gateway(k,'asset-init',jsonb_build_object('id',extra_asset,'mime','image/png','parts',1));
 perform ml_escape.gateway(k,'asset-part',jsonb_build_object('id',extra_asset,'part',0,'data','AA=='));
 p:=jsonb_set(p,'{scenes,0,background,data}',to_jsonb('/api/escape-studio?action=asset&id='||asset));
 perform ml_escape.gateway(k,'save',jsonb_build_object('id',p->>'id','version',1,'data',p,'assets',jsonb_build_array(asset)));
 r:=ml_escape.gateway(k,'publish',jsonb_build_object('id',p->>'id','version',2,'token',tok));
 if r->>'token'<>tok then raise exception 'Publication link was not returned';end if;
 r:=ml_escape.gateway(k,'published',jsonb_build_object('room',tok));
 if r->>'version'<>'2' or r->'data'->>'title' is distinct from p->>'title' then raise exception 'Published snapshot mismatch';end if;
 r:=ml_escape.gateway(k,'asset',jsonb_build_object('id',asset,'room',tok));if r->>'data'<>'AA==' then raise exception 'Published image failed';end if;
 begin perform ml_escape.gateway(k,'asset',jsonb_build_object('id',extra_asset,'room',tok));raise exception 'An unrelated image was exposed';exception when no_data_found then null;end;
 perform ml_escape.gateway(k,'start',jsonb_build_object('room',tok,'session',sid,'proof',proof,'learner','Integration QA'));
 perform ml_escape.gateway(k,'progress',jsonb_build_object('room',tok,'session',sid,'proof',proof,'progress',jsonb_build_object('learner','Integration QA','finished',true,'elapsed',120,'attempts',5,'hints',1,'notes','Completed evidence review.','solved','[]'::jsonb,'log','[]'::jsonb)));
 r:=ml_escape.gateway(k,'reports',jsonb_build_object('id',p->>'id'));if jsonb_array_length(r)<>1 or r->0->>'finished'<>'true' or r->0 ? 'proof_hash' then raise exception 'Completion report failed';end if;
 begin perform ml_escape.gateway(k,'progress',jsonb_build_object('room',tok,'session',sid,'proof',repeat('0',48),'progress','{}'::jsonb));raise exception 'Another session was writable';exception when insufficient_privilege then null;end;
 perform ml_escape.gateway(k,'unpublish',jsonb_build_object('id',p->>'id','version',2));
 begin perform ml_escape.gateway(k,'published',jsonb_build_object('room',tok));raise exception 'An unpublished room remained playable';exception when no_data_found then null;end;
end;
$qa$;
select 'PASS: save, optimistic conflicts, photo upload, room-scoped media, published snapshot, session proof, completion reporting, and unpublishing' as verification;
rollback;